 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    # The uniform non-background border indicates the side toward which the
    # separating line is drawn; the colored object is the remaining non-bg set.
    obj = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, 2)]
    marker_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not obj or not marker_cells:
        return [row[:] for row in grid]
    rs, cs = zip(*obj)
    mr, mc = marker_cells[0]
    out = [row[:] for row in grid]
    if all(r == mr for r, c in marker_cells):
        # Horizontal marker: line parallel to it, just beyond the object's
        # bounding box on the marker-facing side.
        rr = max(rs) + 1 if mr > max(rs) else min(rs) - 1
        if 0 <= rr < h:
            out[rr] = [8] * w
    elif all(c == mc for r, c in marker_cells):
        cc = max(cs) + 1 if mc > max(cs) else min(cs) - 1
        if 0 <= cc < w:
            for r in range(h):
                out[r][cc] = 8
    return out
"
}

