    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    marker_color = min(counts, key=counts.get)
    # Identify the long uniform marker bar and object color as the remaining
    # non-background color(s).
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker_color]
    obj = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg and grid[r][c] != marker_color]
    out = [row[:] for row in grid]
    if not markers or not obj:
        return out
    mr, mc = markers[0]
    rs, cs = zip(*obj)
    if len(set(r for r, c in markers)) == 1:
        # Draw an 8 line immediately outside the object's bounding box, on the
        # side opposite the marker bar.
        rr = min(rs) - 1 if mr > max(rs) else max(rs) + 1
        if 0 <= rr < h:
            out[rr] = [8] * w
    elif len(set(c for r, c in markers)) == 1:
        cc = min(cs) - 1 if mc > max(cs) else max(cs) + 1
        if 0 <= cc < w:
            for r in range(h):
                out[r][cc] = 8
    return out
