 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    marker = min(counts, key=counts.get)
    bg = max(counts, key=counts.get)
    obj = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (marker, bg)]
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    out = [row[:] for row in grid]
    if not obj or not marks:
        return out
    rs, cs = zip(*obj)
    mr, mc = marks[0]
    if len({r for r, c in marks}) == 1:
        # Horizontal marker bar: put a full-width divider immediately beyond
        # the object toward the marker, unless it touches the marker, then
        # place the divider on the far side.
        if mr > max(rs):
            rr = min(rs) - 1 if mr - max(rs) == 1 else max(rs) + 1
        else:
            rr = max(rs) + 1 if min(rs) - mr == 1 else min(rs) - 1
        if 0 <= rr < h:
            out[rr] = [8] * w
    elif len({c for r, c in marks}) == 1:
        if mc > max(cs):
            cc = min(cs) - 1 if mc - max(cs) == 1 else max(cs) + 1
        else:
            cc = max(cs) + 1 if min(cs) - mc == 1 else min(cs) - 1
        if 0 <= cc < w:
            for r in range(h):
                out[r][cc] = 8
    return out
